From 36c81beeb74c360a813cb198d3b534a3daf8be37 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:47:12 +0100
Subject: [PATCH] libnotificationmanager: rate limit new notifications per
 application

An application sending thousands of notifications in a burst kept the
shell busy for many seconds and grew its memory by about a gigabyte. Now
each application may create at most 50 notifications every 10 seconds.

BUG: 483481
---
 libnotificationmanager/server_p.cpp | 32 +++++++++++++++++++++++++++++
 libnotificationmanager/server_p.h   |  7 +++++++
 2 files changed, 39 insertions(+)

diff --git a/libnotificationmanager/server_p.cpp b/libnotificationmanager/server_p.cpp
index 76f91abcba..142820b431 100644
--- a/libnotificationmanager/server_p.cpp
+++ b/libnotificationmanager/server_p.cpp
@@ -27,8 +27,13 @@
 #include <KSharedConfig>
 #include <KUser>

+using namespace std::chrono_literals;
+
 using namespace NotificationManager;

+static constexpr int s_rateLimitCount = 50;
+static constexpr auto s_rateLimitWindow = 10s;
+
 ServerPrivate::ServerPrivate(QObject *parent)
     : QObject(parent)
     , m_inhibitionWatcher(new QDBusServiceWatcher(this))
@@ -142,6 +147,33 @@ uint ServerPrivate::Notify(const QString &app_name,
                            int timeout)
 {
     const bool wasReplaced = replaces_id > 0;
+
+    // If an application floods us with new notifications, refuse the excess so it can't make the shell unresponsive
+    if (!wasReplaced) {
+        QString rateLimitKey = hints.value(QStringLiteral("desktop-entry")).toString();
+        if (rateLimitKey.isEmpty()) {
+            rateLimitKey = !app_name.isEmpty() ? app_name : message().service();
+        }
+        auto rateLimit = m_rateLimits.find(rateLimitKey);
+        if (rateLimit == m_rateLimits.end() || rateLimit->window.durationElapsed() > s_rateLimitWindow) {
+            m_rateLimits.removeIf([](const auto &it) {
+                return it.value().window.durationElapsed() > s_rateLimitWindow;
+            });
+            rateLimit = m_rateLimits.insert(rateLimitKey, RateLimit());
+            rateLimit->window.start();
+        }
+
+        if (++rateLimit->count > s_rateLimitCount) {
+            if (rateLimit->count == s_rateLimitCount + 1) {
+                qCWarning(NOTIFICATIONMANAGER) << "Application" << rateLimitKey << "sent too many notifications in quick succession, discarding the excess";
+            }
+
+            sendErrorReply(QStringLiteral("org.freedesktop.Notifications.Error.ExcessNotificationGeneration"),
+                           QStringLiteral("Created too many notifications in quick succession"));
+            return 0;
+        }
+    }
+
     uint notificationId = 0;
     if (wasReplaced) {
         notificationId = replaces_id;
diff --git a/libnotificationmanager/server_p.h b/libnotificationmanager/server_p.h
index 0c7f42c26f..55279a74d0 100644
--- a/libnotificationmanager/server_p.h
+++ b/libnotificationmanager/server_p.h
@@ -7,6 +7,7 @@
 #pragma once

 #include <QDBusContext>
+#include <QElapsedTimer>
 #include <QObject>
 #include <QSet>
 #include <QStringList>
@@ -127,6 +128,12 @@ private:
     bool m_inhibited = false;

     Notification m_lastNotification;
+
+    struct RateLimit {
+        QElapsedTimer window;
+        int count = 0;
+    };
+    QHash<QString /*desktop entry or app name*/, RateLimit> m_rateLimits;
 };

 } // namespace NotificationManager
